using GrimmDiff.Domain;
namespace GrimmDiff.Application;
public sealed class DiffAnalysisService(IRepositoryDiffReader diffs, IDiffAnalysisProvider aiProvider, IDiffAnalysisProvider heuristicProvider)
{ public async Task<DiffAnalysisView> AnalyzeAsync(DiffAnalysisQuery query, CancellationToken cancellationToken = default) { var historical = !string.IsNullOrWhiteSpace(query.CommitId); var diff = historical ? await diffs.GetCommitDiffAsync(query.RepositoryPath, query.CommitId!, cancellationToken: cancellationToken) : (await diffs.GetDiffAsync(query.RepositoryPath, DiffScope.Staged, cancellationToken: cancellationToken)) + (await diffs.GetDiffAsync(query.RepositoryPath, DiffScope.WorkingTree, cancellationToken: cancellationToken)); var request = new DiffAnalysisRequest(query.RepositoryPath, historical ? DiffScope.Historical : DiffScope.WorkingTree, diff, query.Language); return new(await (query.UseAi ? aiProvider : heuristicProvider).AnalyzeAsync(request, cancellationToken), query.UseAi); } }
